// Surface textures generated by tools/generate-textures.py, in texture-array layer order.
// They are surface detail only: the shader lays out blocks, flagstones and planks and
// multiplies a texture on top (PLAN.md 8.4).
// scale = world units (tiles) per repeat.
// bump = relief strength for the normal map derived from the texture's brightness: dark pits,
// chisel marks and grain become grooves.
export const TEXTURES = [
  ['stone', 1.6, 0.8], ['flag', 2.2, 0.5], ['cave', 3, 1.0], ['oak', 1.2, 0.5],
  ['wood', 1.2, 0.5], ['iron', 0.8, 0.6], ['greenstone', 2.5, 0.3], ['marble', 3, 0.3],
];
export const T = Object.fromEntries(TEXTURES.map(([id], k) => [id, k]));
